changeSet.sql:
CREATE TABLE nexus.identity_counters ( tenant_id TEXT NOT NULL, last_n BIGINT NOT NULL, CONSTRAINT identity_counters_pk PRIMARY KEY (tenant_id) );
CREATE TABLE nexus.identity_records ( tenant_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL, parent TEXT, generation INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, display_name TEXT, creator TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, lease TEXT, last_renewal TIMESTAMPTZ, lapsed_at TIMESTAMPTZ, gone_at TIMESTAMPTZ, client_version TEXT, holder_session_id TEXT, holder_host TEXT, holder_pid INTEGER, holder_started_at BIGINT, holder_proc_start TEXT, holder_pane TEXT, last_binding_seq INTEGER NOT NULL DEFAULT 0, CONSTRAINT identity_records_pk PRIMARY KEY (tenant_id, id), CONSTRAINT identity_records_kind_ck CHECK (kind IN ('seat', 'ephemeral', 'delegated')), CONSTRAINT identity_records_state_ck CHECK (state IN ('unheld', 'live', 'lapsed', 'ended')), CONSTRAINT identity_records_lease_ck CHECK (lease IS NULL OR lease IN ('leased', 'unleased')), CONSTRAINT identity_records_creator_ck CHECK (creator IN ('sam', 'restart', 'session', 'dispatch')) );
-- The bindings-by-host route and the SessionStart sweep read the live and lapsed holders of one host. CREATE INDEX idx_identity_records_holder_host ON nexus.identity_records (tenant_id, holder_host) WHERE state IN ('live', 'lapsed'); -- Retention reads the ended and lapsed non-seat identities. CREATE INDEX idx_identity_records_retention ON nexus.identity_records (tenant_id, state) WHERE kind <> 'seat';
ALTER TABLE nexus.identity_counters ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.identity_counters FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.identity_counters USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
ALTER TABLE nexus.identity_records ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.identity_records FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.identity_records USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE TABLE nexus.identity_aliases (
    tenant_id    TEXT        NOT NULL,
    name         TEXT        NOT NULL,
    identity_id  TEXT        NOT NULL,
    state        TEXT        NOT NULL,
    since        TIMESTAMPTZ NOT NULL,
    retired_at   TIMESTAMPTZ,
    renamed_to   TEXT,
    CONSTRAINT identity_aliases_pk PRIMARY KEY (tenant_id, name),
    CONSTRAINT identity_aliases_identity_fk FOREIGN KEY (tenant_id, identity_id)
        REFERENCES nexus.identity_records (tenant_id, id),
    CONSTRAINT identity_aliases_state_ck CHECK (state IN ('live', 'retired'))
);

CREATE UNIQUE INDEX uq_identity_aliases_one_live ON nexus.identity_aliases (tenant_id, identity_id)
    WHERE state = 'live';

ALTER TABLE nexus.identity_aliases ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.identity_aliases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.identity_aliases
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE TABLE nexus.identity_bindings ( tenant_id TEXT NOT NULL, identity_id TEXT NOT NULL, seq INTEGER NOT NULL, event TEXT NOT NULL, generation INTEGER NOT NULL, lease TEXT, session_id TEXT, host TEXT, pid INTEGER, started_at BIGINT, proc_start TEXT, pane TEXT, client_version TEXT, prior_session_id TEXT, holder_gone JSONB, detail TEXT, at TIMESTAMPTZ NOT NULL, CONSTRAINT identity_bindings_pk PRIMARY KEY (tenant_id, identity_id, seq), CONSTRAINT identity_bindings_identity_fk FOREIGN KEY (tenant_id, identity_id) REFERENCES nexus.identity_records (tenant_id, id) ON DELETE CASCADE, CONSTRAINT identity_bindings_event_ck CHECK (event IN ('start', 'clear', 'resume', 'fork', 'takeover', 'release', 'rename', 'end', 'lapse', 'revive', 'gone')), CONSTRAINT identity_bindings_lease_ck CHECK (lease IS NULL OR lease IN ('leased', 'unleased')) );
CREATE TABLE nexus.identity_sessions ( tenant_id TEXT NOT NULL, session_id TEXT NOT NULL, identity_id TEXT NOT NULL, generation INTEGER NOT NULL, at TIMESTAMPTZ NOT NULL, CONSTRAINT identity_sessions_pk PRIMARY KEY (tenant_id, session_id), CONSTRAINT identity_sessions_identity_fk FOREIGN KEY (tenant_id, identity_id) REFERENCES nexus.identity_records (tenant_id, id) ON DELETE CASCADE );
CREATE INDEX idx_identity_sessions_identity ON nexus.identity_sessions (tenant_id, identity_id);
ALTER TABLE nexus.identity_bindings ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.identity_bindings FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.identity_bindings USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
ALTER TABLE nexus.identity_sessions ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.identity_sessions FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.identity_sessions USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE TABLE nexus.identity_memberships (
    tenant_id    TEXT        NOT NULL,
    identity_id  TEXT        NOT NULL,
    group_name   TEXT        NOT NULL,
    role         TEXT        NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL,
    CONSTRAINT identity_memberships_pk PRIMARY KEY (tenant_id, identity_id, group_name),
    CONSTRAINT identity_memberships_identity_fk FOREIGN KEY (tenant_id, identity_id)
        REFERENCES nexus.identity_records (tenant_id, id) ON DELETE CASCADE,
    CONSTRAINT identity_memberships_role_ck CHECK (role IN ('leader', 'member'))
);

-- A group's roster in join order.
CREATE INDEX idx_identity_memberships_group ON nexus.identity_memberships (tenant_id, group_name, created_at, identity_id);

ALTER TABLE nexus.identity_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.identity_memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.identity_memberships
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
